INSERT INTO pt_politicas (clave, valor, orden) VALUES ('precioEnBaseDoble', 'Todos los precios publicados son por persona en base doble (habitación compartida con otra persona).', 0)
INSERT INTO pt_politicas (clave, valor, orden) VALUES ('suplementoSingle', 'Si preferís habitación privada sin compartir, se aplica un suplemento del 50% sobre el precio del paquete.', 10)
INSERT INTO pt_politicas (clave, valor, orden) VALUES ('menoresCuatroAnios', 'Los niños menores de 4 años viajan sin cargo en el paquete — solo abonan los gastos administrativos ($10.000 por persona).', 20)
INSERT INTO pt_politicas (clave, valor, orden) VALUES ('cocheCama', 'Todos nuestros viajes se realizan en bus mix. Si deseás viajar en la parte inferior del coche (butaca cama), el costo adicional es de $10.000 por persona.', 30)
INSERT INTO pt_politicas (clave, valor, orden) VALUES ('tipoBus', 'Bus mix con servicio a bordo. La parte inferior (butaca cama) tiene costo adicional de $10.000 por persona.', 40)
INSERT INTO pt_politicas (clave, valor, orden) VALUES ('puntosDeSubida', 'Contamos con múltiples puntos de subida distribuidos en el Gran Buenos Aires: Liniers, Haedo, Morón, Ituzaingó, Castelar, Palermo, Once y más. Consultá el punto más cercano a vos.', 50)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-101', 'san-jose-cena-show-baile-11sep', 'Termas de San José — Cena Show + Baile · 11 de Septiembre', 'full_day', 'colon-entre-rios', 1, 0, 139000, 10000, 0, 10000, 'Full day a las Termas de San José con desayuno, merienda a bordo, cena show tenedor libre y baile. Edición especial Día del Maestro. Salida 11 de septiembre.', 'Un full day pensado para festejar el Día del Maestro a lo grande. Salimos en el día hacia las Termas de San José, en Colón (Entre Ríos), con desayuno y merienda a bordo, entrada y traslado a las termas incluidos, y a la noche una cena show tenedor libre con baile para cerrar la jornada a puro festejo. Coordinador durante todo el viaje y bus semi cama con servicio a bordo desde el Gran Buenos Aires.', '["Bus semi cama con servicio a bordo","Desayuno","Merienda a bordo","Entrada y traslado a Termas de San José","Cena show tenedor libre + baile","Coordinador de viaje"]', '["Almuerzo","Gastos personales","Bebidas extra"]', '/termas-san-jose-1.jpg', '["/termas-san-jose-1.jpg","/termas-san-jose-2.jpg","/termas-san-jose-4.jpg","/termas-san-jose-5.jpg"]', 4.9, 74, 30, '2026-09-11', 'mensual', '["termas","fiesta","relax","litoral","full day"]', '["Salida temprano desde los puntos de subida del GBA en bus semi cama. Desayuno y merienda a bordo.","Llegada a Colón. Día completo en las Termas de San José (entrada y traslado incluidos).","Noche: cena show tenedor libre con baile. Regreso a Buenos Aires al finalizar."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona. Viaje en el día (full day), no requiere alojamiento.","suplementoSingle":"Viaje en el día: no aplica suplemento por habitación individual.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000).","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-102', 'colon-termas-colon-cena-show-12sep', 'Colón + Termas de Colón + Cena Show · 12 de Septiembre', 'viaje_completo', 'colon-entre-rios', 2, 1, 162000, 10000, 81000, 10000, '2 días / 1 noche en Hostería El Abuelo. Media pensión, cena show tenedor libre y Termas de Colón. Edición Día del Maestro. Salida 12 de septiembre.', 'Escapada a Colón, Entre Ríos, para festejar el Día del Maestro. Te alojás en la Hostería El Abuelo con media pensión y disfrutás de una cena show con tenedor libre y de las Termas de Colón (entrada incluida). Bus semi cama con servicio a bordo, coordinador de viaje y el encanto del litoral entrerriano: playa de río, termas y buena gastronomía. El segundo día emprendemos el regreso a Buenos Aires a las 17:00 hs desde las termas.', '["Bus semi cama con servicio a bordo","1 noche en Hostería El Abuelo","Media pensión","Cena show tenedor libre","Entrada a Termas de Colón","Coordinador de viaje"]', '["Almuerzo del segundo día","Gastos personales","Excursiones opcionales"]', '/termas-colon-1.jpg', '["/termas-colon-1.jpg","/termas-colon-2.jpg","/termas-san-jose-1.jpg"]', 4.8, 66, 25, '2026-09-12', 'mensual', '["termas","fiesta","relax","litoral","pareja"]', '["Día 1 — Salida nocturna desde el GBA en bus semi cama con servicio a bordo.","Día 2 — Llegada a Colón. Check-in en Hostería El Abuelo. Tarde: Termas de Colón (entrada incluida). Noche: cena show tenedor libre.","Día 3 — Desayuno. Check-out. Regreso a Buenos Aires a partir de las 17:00 hs desde las termas."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $81.000 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-103', 'san-bernardo-hotel-colores-12sep', 'San Bernardo — Hotel Colores · 12 de Septiembre', 'viaje_completo', 'san-bernardo', 2, 1, 98000, 10000, 49000, 10000, '2 días / 1 noche en Hotel Colores (pileta, a 200 mts de la playa). Desayuno, coordinador y bus mix. Edición Día del Maestro. Salida 12 de septiembre.', 'Escapada de fin de semana a San Bernardo para festejar el Día del Maestro. Te alojás en el Hotel Colores, con pileta y a solo 200 metros de la playa, con desayuno incluido. Coordinador de viaje y bus mix con servicio a bordo desde el Gran Buenos Aires. El segundo día emprendemos el regreso a Buenos Aires en horas de la tarde.', '["Bus mix con servicio a bordo","1 noche en Hotel Colores","Desayuno","Acceso a pileta del hotel","Coordinador de viaje"]', '["Almuerzo y cena","Gastos personales","Excursiones"]', '/san-bernardo.jpg', '["/san-bernardo.jpg","/hostal-del-sol-1.jpg"]', 4.6, 58, 25, '2026-09-12', 'quincenal', '["playa","familia","relax","finde"]', '["Día 1 — Salida nocturna desde los puntos de subida del GBA en bus mix.","Día 2 — Llegada a San Bernardo. Check-in Hotel Colores. Desayuno. Día libre en la playa y el hotel.","Día 3 — Desayuno. Mañana libre. Regreso a Buenos Aires en horas de la tarde."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $49.000 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
