  ('pkg-104', 'villa-elisa-full-day-13sep', 'Termas de Villa Elisa — Full Day · 13 y 20 de Septiembre', 'full_day', 'villa-elisa-entre-rios', 1, 0, 85000, 10000, 0, 10000, 'Full day a las Termas de Villa Elisa (Entre Ríos) con entrada, traslado, coordinador y bus semi cama. Salidas 13 y 20 de septiembre.', 'Un día completo de relax en las Termas de Villa Elisa, uno de los complejos termales más lindos de Entre Ríos, con amplios parques, piscinas de distintas temperaturas y sector spa. El full day incluye entrada y traslado a las termas, coordinador de viaje y bus semi cama con servicio a bordo desde el Gran Buenos Aires. Salidas disponibles el 13 y el 20 de septiembre.', '["Bus semi cama con servicio a bordo","Entrada y traslado a Termas de Villa Elisa","Coordinador de viaje"]', '["Comidas","Gastos personales","Servicios de spa opcionales"]', '/villa-elisa-1.jpg', '["/villa-elisa-1.jpg","/villa-elisa-2.jpg","/villa-elisa-3.jpg"]', 4.7, 41, 30, '2026-09-13', 'quincenal', '["termas","relax","litoral","full day"]', '["Salida temprano desde el GBA en bus semi cama con servicio a bordo.","Día completo en las Termas de Villa Elisa (entrada y traslado incluidos).","Regreso a Buenos Aires al finalizar la jornada."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona. Viaje en el día (full day), no requiere alojamiento.","suplementoSingle":"Viaje en el día: no aplica suplemento por habitación individual.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000).","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
