  ('pkg-105', 'san-jose-full-day-13sep', 'Termas de San José — Full Day · 13 y 27 de Septiembre', 'full_day', 'colon-entre-rios', 1, 0, 120000, 10000, 0, 10000, 'Full day a las Termas de San José con desayuno, merienda a bordo, entrada, traslado y coordinador. Salidas 13 y 27 de septiembre.', 'Un día completo de termas y relax en Colón, Entre Ríos. El full day a las Termas de San José incluye desayuno y merienda a bordo, entrada y traslado a las termas, coordinador de viaje y bus semi cama con servicio a bordo desde el Gran Buenos Aires. Salidas disponibles el 13 y el 27 de septiembre.', '["Bus semi cama con servicio a bordo","Desayuno","Merienda a bordo","Entrada y traslado a Termas de San José","Coordinador de viaje"]', '["Almuerzo","Gastos personales","Bebidas extra"]', '/termas-san-jose-1.jpg', '["/termas-san-jose-1.jpg","/termas-san-jose-2.jpg","/termas-san-jose-3.jpg"]', 4.8, 88, 30, '2026-09-13', 'quincenal', '["termas","relax","litoral","full day"]', '["Salida temprano desde el GBA en bus semi cama. Desayuno y merienda a bordo.","Día completo en las Termas de San José (entrada y traslado incluidos).","Regreso a Buenos Aires al finalizar la jornada."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona. Viaje en el día (full day), no requiere alojamiento.","suplementoSingle":"Viaje en el día: no aplica suplemento por habitación individual.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000).","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
