  ('pkg-106', 'termas-colon-full-day-13sep', 'Termas de Colón — Full Day · 13 y 27 de Septiembre', 'full_day', 'colon-entre-rios', 1, 0, 139000, 10000, 0, 10000, 'Full day a las Termas de Colón con desayuno, almuerzo, merienda a bordo, entrada, traslado y coordinador. Salidas 13 y 27 de septiembre.', 'Un día completo en las Termas de Colón, Entre Ríos, con pensión incluida: desayuno, almuerzo y merienda a bordo. El full day incluye entrada y traslado a las termas, coordinador de viaje y bus semi cama con servicio a bordo desde el Gran Buenos Aires. Salidas disponibles el 13 y el 27 de septiembre.', '["Bus semi cama con servicio a bordo","Desayuno","Almuerzo","Merienda a bordo","Entrada y traslado a Termas de Colón","Coordinador de viaje"]', '["Gastos personales","Bebidas extra"]', '/termas-colon-1.jpg', '["/termas-colon-1.jpg","/termas-colon-2.jpg"]', 4.8, 79, 30, '2026-09-13', 'quincenal', '["termas","relax","litoral","full day"]', '["Salida temprano desde el GBA en bus semi cama. Desayuno a bordo.","Día completo en las Termas de Colón (entrada y traslado incluidos). Almuerzo incluido.","Merienda a bordo y regreso a Buenos Aires al finalizar la jornada."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona. Viaje en el día (full day), no requiere alojamiento.","suplementoSingle":"Viaje en el día: no aplica suplemento por habitación individual.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000).","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-107', 'rio-hondo-hebron-promo-16sep', 'Termas de Río Hondo — Hotel Hebrón (PROMO) · 16 de Septiembre', 'viaje_completo', 'rio-hondo', 7, 4, 199000, 10000, 99500, 10000, 'PROMO $199.000 (antes $290.000). 7 días / 4 noches en Hotel Hebrón ★★. Pensión completa + merienda, show en el hotel y clase de aquagym. Salida 16 de septiembre.', 'Las Termas de Río Hondo, en Santiago del Estero, son uno de los destinos termales más reconocidos de Argentina. Aprovechá esta PROMO: 7 días con alojamiento en el Hotel Hebrón ★★, con pensión completa más merienda (desayuno, almuerzo, merienda y cena), show en el hotel y clase de aquagym. Bus mix con servicio a bordo desde el Gran Buenos Aires. Un descanso total con todo resuelto, a un precio promocional por tiempo limitado.', '["Bus mix con servicio a bordo","4 noches en Hotel Hebrón ★★","Pensión completa (desayuno, almuerzo, merienda y cena)","Show en el hotel","Clase de aquagym"]', '["Gastos personales","Excursiones opcionales fuera del hotel","Bebidas extra"]', '/rio-hondo-1.jpg', '["/rio-hondo-1.jpg"]', 4.8, 156, 20, '2026-09-16', 'mensual', '["termas","relax","pareja","naturaleza","norte"]', '["Día 1 — Salida nocturna desde el GBA en bus mix con servicio a bordo.","Día 2 — Llegada a Río Hondo. Check-in Hotel Hebrón. Pensión completa. Tarde libre en las termas. Show nocturno.","Día 3 — Pensión completa + merienda. Clase de aquagym. Día de relax en el hotel y las termas.","Día 4 — Pensión completa + merienda. Día libre. Show en el hotel.","Día 5 — Pensión completa + merienda. Día libre en las termas.","Día 6 — Desayuno. Check-out. Inicio del regreso a Buenos Aires.","Día 7 — Llegada a Buenos Aires."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once","La Plata"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $99.500 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-108', 'tandil-full-day-19sep', 'Tandil — Full Day · 19 de Septiembre', 'full_day', 'tandil', 1, 0, 85000, 6000, 0, 10000, 'Full day a Tandil: Cerro Centinela, Monte Calvario, Lago, Parque Independencia, Castillo Morisco, Dique del Fuerte, Piedra Movediza y compras regionales. Con guía local. Salida 19 de septiembre.', 'Un día a pura sierra en Tandil. Recorremos los clásicos: Cerro Centinela, Monte Calvario, el Lago del Fuerte, el Parque Independencia con su Castillo Morisco, el Dique del Fuerte y la famosa Piedra Movediza, con tiempo para las compras de productos regionales (salames y quesos). Incluye bus mix con merienda a bordo, coordinador y guía local. Un full day ideal para disfrutar el paisaje serrano y la gastronomía tandilense.', '["Bus mix con servicio a bordo","Merienda a bordo","Coordinador de viaje","Guía local","Recorrido: Cerro Centinela, Monte Calvario, Lago, Parque Independencia, Castillo Morisco, Dique del Fuerte y Piedra Movediza"]', '["Almuerzo","Compras y productos regionales","Gastos personales"]', '/tandil-1.jpg', '["/tandil-1.jpg","/tandil-2.jpg","/tandil-3.jpg","/tandil-4.jpg","/tandil-5.jpg"]', 4.8, 52, 30, '2026-09-19', 'mensual', '["sierras","naturaleza","gastronomía","full day"]', '["Salida temprano desde el GBA en bus mix con servicio a bordo. Merienda a bordo.","Llegada a Tandil. Recorrido con guía local: Cerro Centinela, Monte Calvario, Lago del Fuerte, Parque Independencia y Castillo Morisco, Dique del Fuerte y Piedra Movediza.","Tiempo libre para compras regionales. Regreso a Buenos Aires al finalizar la jornada."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona. Viaje en el día (full day), no requiere alojamiento.","suplementoSingle":"Viaje en el día: no aplica suplemento por habitación individual.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($6.000).","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-109', 'mar-del-plata-riazor-19sep', 'Mar del Plata — Hotel Riazor · Septiembre y Octubre', 'viaje_completo', 'mar-del-plata', 2, 1, 119000, 10000, 59500, 10000, '2 días / 1 noche en Hotel Riazor (frente al shopping, a 400 mts del centro Güemes). Pensión completa, show en el hotel y bus mix. Salidas sábados y domingos.', 'Escapada de fin de semana a Mar del Plata con todo resuelto. Te alojás en el Hotel Riazor, frente al Shopping Los Gallegos y a 400 metros del centro comercial Güemes, en pleno corazón de la ciudad. El paquete incluye pensión completa, show en el hotel y traslado en bus mix con servicio a bordo. Salidas confirmadas: sábados y domingos de septiembre (19 y 26) y de octubre (del 3 al 31). El segundo día emprendemos el regreso a Buenos Aires en horas de la tarde.', '["Bus mix con servicio a bordo","1 noche en Hotel Riazor","Pensión completa (desayuno, almuerzo y cena)","Show en el hotel","Coordinador de viaje"]', '["Bebidas con las comidas","Gastos personales","Excursiones opcionales"]', '/mar-del-plata-5.jpg', '["/mar-del-plata-5.jpg","/hotel-riazor-1.jpg","/hotel-riazor-2.jpg","/hotel-riazor-3.jpg","/hotel-riazor-4.jpg"]', 4.8, 148, 20, '2026-09-19', 'semanal', '["playa","familia","relax","finde"]', '["Día 1 — Salida nocturna desde los puntos de subida del GBA en bus mix.","Día 2 — Llegada a Mar del Plata. Check-in Hotel Riazor. Pensión completa. Tarde libre en la ciudad, la rambla y el centro Güemes. Show en el hotel.","Día 3 — Desayuno. Regreso a Buenos Aires en horas de la tarde."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $59.500 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
