  ('pkg-110', 'san-bernardo-hostal-del-sol-19sep', 'San Bernardo — Hostal del Sol Resort & Spa ★★★★ · Septiembre y Octubre', 'viaje_completo', 'san-bernardo', 2, 1, 135000, 10000, 67500, 10000, '2 días / 1 noche en Hostal del Sol Resort & Spa ★★★★ (pileta climatizada, gimnasio, sala de juegos, canchas). Desayuno buffet y bus mix. Salidas sábados y domingos.', 'Fin de semana en el mejor resort de San Bernardo. El Hostal del Sol Resort & Spa 4 estrellas es ideal para descansar y divertirse: pileta climatizada, gimnasio, sala de juegos y canchas de fútbol y básquet. Incluye desayuno buffet y bus mix con servicio a bordo desde el Gran Buenos Aires. Salidas confirmadas: sábados y domingos del 12, 19 y 26 de septiembre y del 3, 17, 24 y 31 de octubre. El segundo día emprendemos el regreso en horas de la tarde.', '["Bus mix con servicio a bordo","1 noche en Hostal del Sol Resort & Spa ★★★★","Desayuno buffet","Acceso a pileta climatizada, gimnasio y todas las instalaciones","Coordinador de viaje"]', '["Almuerzo y cena","Gastos personales","Excursiones"]', '/san-bernardo.jpg', '["/san-bernardo.jpg","/hostal-del-sol-1.jpg","/hostal-del-sol-2.jpg","/hostal-del-sol-3.jpg","/hostal-del-sol-4.jpg"]', 4.7, 121, 25, '2026-09-19', 'semanal', '["playa","familia","relax","finde","resort"]', '["Día 1 — Salida nocturna desde los puntos de subida del GBA en bus mix.","Día 2 — Llegada a San Bernardo. Check-in Hostal del Sol Resort & Spa. Desayuno buffet. Día libre en el resort y la playa.","Día 3 — Desayuno. Mañana libre. Regreso a Buenos Aires en horas de la tarde."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $67.500 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
INSERT INTO pt_paquetes (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, activo) VALUES
  ('pkg-111', 'federacion-los-angelitos-25sep', 'Federación — Hotel Los Angelitos · 25 de Septiembre', 'viaje_completo', 'federacion-entre-rios', 4, 3, 175000, 10000, 87500, 10000, '4 días / 3 noches en Hotel Los Angelitos. 3 desayunos y bus semi cama. El gran parque termal de Federación (Entre Ríos). Salida 25 de septiembre.', 'Federación, en Entre Ríos, es sinónimo de termas: su parque termal es uno de los más grandes y completos del país, con piscinas de distintas temperaturas y un enorme parque acuático. Te alojás en el Hotel Los Angelitos con 3 desayunos incluidos y viajás en bus semi cama con servicio a bordo desde el Gran Buenos Aires. Cuatro días para relajarte en las aguas termales y disfrutar de la tranquilidad de la ciudad.', '["Bus semi cama con servicio a bordo","3 noches en Hotel Los Angelitos","3 desayunos","Coordinador de viaje"]', '["Almuerzos y cenas","Entradas al parque termal","Gastos personales"]', '/federacion-1.jpg', '["/federacion-1.jpg","/federacion-2.jpg","/federacion-3.jpg"]', 4.8, 63, 22, '2026-09-25', 'mensual', '["termas","relax","familia","litoral"]', '["Día 1 — Salida nocturna desde el GBA en bus semi cama con servicio a bordo.","Día 2 — Llegada a Federación. Check-in Hotel Los Angelitos. Desayuno. Día libre en el parque termal.","Día 3 — Desayuno. Día completo de termas y relax.","Día 4 — Desayuno. Check-out. Regreso a Buenos Aires."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once","La Plata"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $87.500 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
