  ('pkg-112', 'san-pedro-howard-johnson-03oct', 'San Pedro — Howard Johnson ★★★★ · 3 de Octubre', 'viaje_completo', 'san-pedro', 2, 1, 195000, 10000, 97500, 10000, '2 días / 1 noche en Howard Johnson ★★★★ San Pedro. Media pensión + bebida, traslado a la campiña y bus semi cama. Salida 3 de octubre.', 'Escapada de fin de semana a San Pedro, en el Howard Johnson 4 estrellas. El sábado te alojás en el Howard Johnson Hotel & Spa (centro) y el domingo disfrutás del Howard Johnson Marinas Resort. Incluye media pensión con bebida, traslado a la campiña (no incluye entrada) y bus semi cama con servicio a bordo desde el Gran Buenos Aires. Comodidad de resort a pocas horas de Buenos Aires.', '["Bus semi cama con servicio a bordo","1 noche en Howard Johnson ★★★★ (Hotel & Spa / Marinas Resort)","Media pensión + bebida","Traslado a la campiña","Coordinador de viaje"]', '["Entrada a la campiña","Gastos personales","Excursiones opcionales"]', '/san-pedro-1.jpg', '["/san-pedro-1.jpg","/san-pedro-2.jpg","/san-pedro-3.jpg","/san-pedro-4.jpg","/san-pedro-5.jpg","/san-pedro-6.jpg","/san-pedro-7.jpg","/san-pedro-8.jpg"]', 4.7, 47, 22, '2026-10-03', 'mensual', '["resort","relax","pareja","spa"]', '["Día 1 (sábado) — Salida desde el GBA en bus semi cama. Llegada a San Pedro. Check-in Howard Johnson Hotel & Spa (centro). Media pensión.","Día 2 (domingo) — Desayuno. Día en el Howard Johnson Marinas Resort. Traslado a la campiña. Regreso a Buenos Aires.","Regreso a Buenos Aires al finalizar el segundo día."]', '["Liniers","Haedo","Morón","Ituzaingó","Castelar","Palermo","Once"]', '{"precioEnBaseDoble":"Precio por persona en base doble (habitación compartida).","suplementoSingle":"Suplemento habitación individual: $97.500 adicionales sobre el precio del paquete.","menoresCuatroAnios":"Niños menores de 4 años: solo abonan gastos administrativos ($10.000). Sin cargo de paquete.","cocheCama":"Butaca cama (parte inferior del bus): $10.000 adicionales por persona. Sujeto a disponibilidad."}', 1)
